// Every Material Symbols Rounded icon the public estimate page renders.
// SOURCE OF TRUTH for src/fonts/material-symbols-rounded.woff2, generated by
// `npm run icons:build`.
//
// Kept separate from src/components/icon-names.ts so the app keeps ONE
// Outlined subset and the public page loads only the Rounded glyphs it uses
// (design spec §1: Material Symbols Rounded on /e/[token] only). A name
// missing from this list renders as its literal ligature text, so the page's
// icon component types `name` as EstIconName and a missing name fails the
// type-check.
export const ESTIMATE_ICON_NAMES = [
  'attach_file',
  'bookmark',
  'call',
  'check',
  'check_circle',
  'chevron_left',
  'chevron_right',
  'close',
  'content_copy',
  'draw',
  'error_outline',
  'event_busy',
  'expand_more',
  'hourglass_empty',
  'keyboard',
  'link_off',
  'open_in_new',
  'restart_alt',
  'schedule',
  'sms',
  'verified',
  'visibility',
] as const;

export type EstIconName = (typeof ESTIMATE_ICON_NAMES)[number];
